import {esc,fmt}from'../../ui/format.js';import{FIELDS,effective}from'../../core/model.js';
export function calibrationView({m}){const rows=m.nodes.flatMap(n=>Object.entries(n.calibration||{}).map(([key,v])=>({n,key,...v})));return `<section class="page-intro"><div><div class="eyebrow">ÎNCREDERE ÎN DATE</div><h1>Calibrare & proveniență</h1><p>Separă specificațiile de producător, măsurătorile și ipotezele de lucru.</p></div></section><div class="notice">Fișele comerciale documentează limite tehnice. Timpii de ciclu, rebutul, costurile și MTBF/MTTR necesită date din proces. Valorile neutre de configurare nu sunt date măsurate.</div><div class="panel tablewrap"><table><thead><tr><th>Element</th><th>Parametru</th><th>Valoare modelată</th><th>Proveniență</th><th></th></tr></thead><tbody>${rows.sort((a,b)=>(a.status==='required'?-1:1)-(b.status==='required'?-1:1)).map(r=>`<tr><td>${esc(r.n.name)}</td><td>${esc(FIELDS[r.key][0])}</td><td>${fmt(effective(m,r.n)[r.key],4)} ${esc(FIELDS[r.key][1])}</td><td><span class="badge ${r.status==='required'?'amber':''}">${r.status==='required'?'De calibrat':r.status==='measured'?'Măsurat':r.status==='manufacturer'?'Producător':'Ipoteză'}</span><small class="block">${esc(r.note)}</small></td><td><button data-calibrate="${esc(r.n.id)}" data-param="${r.key}">Editează</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<p>Elementele vechi nu au proveniență explicită. Marchează parametrii din inspector înainte de a considera modelul calibrat.</p>'}</div>`}
